// VerifySchema compares the live table's columns — names and order —
// against the generated schema. This store cannot create or repair
// its table (generated ExternallyProvisioned), so nothing here
// constrains the live shape, and the decode is positional: drift
// fails late or, for same-typed column swaps, silently. Run
// VerifySchema at startup, before the first read;
// facts_ddl_clickhouse.out.sql states the shape it expects.
//
// It checks the COLUMN contract only. The membership-id contract is not
// checked and cannot be from the schema alone: the ids live in the
// membership columns as ordinary values, and a FAT table legitimately
// carries other kinds' ids beside this store's. Rows written under a
// different id assignment therefore pass VerifySchema and then match
// nothing — every component decodes absent, with no error. Compare
// SysmetricsMembershipIds against the writer's assignment when pointing this
// store at rows it did not write.
//
// MATERIALIZED and ALIAS columns are skipped. They are not in SELECT *,
// so the positional decode never sees them, and a table may legitimately
// carry them beside the generated shape — derived tree or routing columns
// added by ALTER after EnsureTable, which is how a store gets skip indexes
// over values its leeway attributes only encode. Counting them would fail
// every such table while the contract this verb guards still held.
func (inst *SysmetricsStore) VerifySchema(ctx context.Context) (err error) {
	live := make([]string, 0, 64)
	for rec, rerr := range inst.exec.QueryArrow(ctx, "DESCRIBE TABLE "+inst.tableName()+factsArrowOutputSettings) {
		if rerr != nil {
			err = eh.Errorf("describe table %s: %w", inst.tableName(), rerr)
			return
		}
		names, ok := rec.Column(0).(*array.String)
		if !ok {
			err = eh.Errorf("describe table %s: name column is %s, not a string", inst.tableName(), rec.Column(0).DataType())
			rec.Release()
			return
		}
		kinds, ok := rec.Column(2).(*array.String)
		if !ok {
			err = eh.Errorf("describe table %s: default_type column is %s, not a string", inst.tableName(), rec.Column(2).DataType())
			rec.Release()
			return
		}
		for i := range int(rec.NumRows()) {
			switch kinds.Value(i) {
			case "MATERIALIZED", "ALIAS":
				continue
			}
			live = append(live, names.Value(i))
		}
		rec.Release()
	}
	want := lowlevel.CreateSchemaFactsTable().Fields()
	if len(live) != len(want) {
		err = eh.Errorf("schema drift on %s: table has %d columns, the generated schema expects %d — regenerated code against an old table (or vice versa); migrate or regenerate", inst.tableName(), len(live), len(want))
		return
	}
	for i, f := range want {
		if live[i] != f.Name {
			err = eh.Errorf("schema drift on %s: column %d is %q, the generated schema expects %q — the decode is positional; migrate or regenerate", inst.tableName(), i, live[i], f.Name)
			return
		}
	}
	return
}

